/* ======================= Texturen (Asphalt015, Metal048A) ======================= */
const TEXB = {"asphC": "data:image/jpeg;base64,", "asphN": "data:image/jpeg;base64,", "asphR": "data:image/jpeg;base64,", "metC": "data:image/jpeg;base64,", "metN": "data:image/jpeg;base64,", "metR": "data:image/jpeg;base64,", "met2C": "data:image/jpeg;base64,", "met2N": "data:image/jpeg;base64,", "brkC": "data:image/jpeg;base64,", "brkN": "data:image/jpeg;base64,", "plkC": "data:image/jpeg;base64,", "plkN": "data:image/jpeg;base64,", "woodC": "data:image/jpeg;base64,", "marC": "data:image/jpeg;base64,", "cardC": "data:image/jpeg;base64,", "skyC": "data:image/jpeg;base64,"};
TEXB.plaC = "data:image/jpeg;base64,";
TEXB.plaN = "data:image/jpeg;base64,";
TEXB.plaR = "data:image/jpeg;base64,";
TEXB.mtlC = "data:image/jpeg;base64,";
TEXB.mtlN = "data:image/jpeg;base64,";
TEXB.mtlR = "data:image/jpeg;base64,";
TEXB.fncC = "data:image/jpeg;base64,";
TEXB.fncN = "data:image/jpeg;base64,";
TEXB.fncA = "data:image/jpeg;base64,";
TEXB.pipC = "data:image/jpeg;base64,";
TEXB.pipN = "data:image/jpeg;base64,";
TEXB.pipR = "data:image/jpeg;base64,";
TEXB.rustC = "data:image/jpeg;base64,";
TEXB.rustN = "data:image/jpeg;base64,";
TEXB.rustR = "data:image/jpeg;base64,";
TEXB.steelC = "data:image/jpeg;base64,";
TEXB.steelN = "data:image/jpeg;base64,";
TEXB.leaC = "data:image/jpeg;base64,";
TEXB.leaN = "data:image/jpeg;base64,";
TEXB.leaR = "data:image/jpeg;base64,";
TEXB.m52C = "data:image/jpeg;base64,";
TEXB.m52N = "data:image/jpeg;base64,";
TEXB.m52R = "data:image/jpeg;base64,";
TEXB.m38C = "data:image/jpeg;base64,";
TEXB.m38N = "data:image/jpeg;base64,";
TEXB.m38R = "data:image/jpeg;base64,";
const TIMG = {};
for (const k in TEXB) { const im = new Image(); im.src = TEXB[k]; TIMG[k] = im; }
function imgTex(k, rx, ry) { const t = new THREE.Texture(TIMG[k]); t.wrapS = t.wrapT = THREE.RepeatWrapping; t.repeat.set(rx, ry); t.anisotropy = 4; if (TIMG[k].complete) t.needsUpdate = true; else TIMG[k].addEventListener("load", () => { t.needsUpdate = true; }); return t; }
function pbrMat(kind, rx, ry, tint, metal) {      // kind: "asph" | "met"
  const o = {map:imgTex(kind + "C", rx, ry), roughness:1}; if (TEXB[kind + "N"]) o.normalMap = imgTex(kind + "N", rx, ry); if (TEXB[kind + "R"]) o.roughnessMap = imgTex(kind + "R", rx, ry); if (!TEXB[kind + "R"]) o.roughness = .8;
  const m = new THREE.MeshStandardMaterial(Object.assign(o, { metalness:metal === undefined ? (kind.slice(0, 3) === "met" ? .6 : 0) : metal}));
  if (m.normalMap) m.normalScale.set(1.1, 1.1); if (tint !== undefined) m.color.setHex(tint); return m;
}
const leatherMat = (rx, ry, tint) => pbrMat("lea", rx, ry, tint === undefined ? 0xffffff : tint, 0);
function applyAsphalt(mesh, w, d, tint) { const m = pbrMat("asph", w/2.4, d/2.4, tint); mesh.material.dispose(); mesh.material = m; }
function applyBrick(mesh, w, h, tint) { const m = pbrMat("brk", w/2.6, h/2.6, tint, 0); mesh.material.dispose(); mesh.material = m; }

// ---- Neue Metalltexturen: Rost-Blau (Rohre, Lab-Sockel) + gebürsteter Stahl (Lab-Boden) ----
const _pm = {};
function pipeMat(len) { const k = Math.round(len*2); return _pm[k] || (_pm[k] = pbrMat("pip", .3, Math.max(1, len/1.6), 0xe8e8f0, .45)); }
function labMetal() {
  const R = TIMG.rustC, S = TIMG.steelC; if (!R.complete || !S.complete || !R.naturalWidth || !S.naturalWidth) return;
  const redraw = (tex, draw) => { const c = tex.image, x = c.getContext("2d"); draw(x, c.width, c.height); tex.needsUpdate = true; };
  const band = (x, w, h) => { const y0 = h*.62, bh = h*.38; x.drawImage(R, 0, 0, 512, 512*bh/w, 0, y0, w, bh); x.fillStyle = "rgba(22,44,100,.55)"; x.fillRect(0, y0, w, bh); x.fillStyle = "#4fa9a3"; x.fillRect(0, y0 - 3, w, 6); x.fillStyle = "rgba(12,16,30,.7)"; for (let i = 0; i < 4; i++) x.fillRect(0, y0 + bh*(i + 1)/5, w, 2); };
  const wall = (x, w, h) => { x.fillStyle = "#aab6d2"; x.fillRect(0, 0, w, h); speckle(x, w, h, 4000, .14); band(x, w, h); x.strokeStyle = "rgba(50,54,52,.5)"; x.lineWidth = 3; x.beginPath(); x.moveTo(1, 0); x.lineTo(1, h); x.stroke(); };
  redraw(wallTexA, wall); redraw(wallTexB, wall);
  redraw(floorTex, (x, w, h) => { x.drawImage(S, 0, 0, w, h); x.fillStyle = "rgba(46,66,128,.62)"; x.fillRect(0, 0, w, h); speckle(x, w, h, 3000, .12); x.strokeStyle = "rgba(14,18,34,.85)"; x.lineWidth = 4; x.strokeRect(0, 0, w, h); x.fillStyle = "rgba(14,18,34,.8)"; for (const [a, b] of [[12, 12], [w - 12, 12], [12, h - 12], [w - 12, h - 12]]) { x.beginPath(); x.arc(a, b, 3.5, 0, 7); x.fill(); } });
  const done = new Set(); scene.traverse(o => { const m = o.isMesh && o.material; if (m && m.color && !done.has(m) && m.color.getHex() === 0x3a4a70 && Math.abs(m.metalness - .55) < .01) { done.add(m); m.map = imgTex("rustC", .5, 1); m.normalMap = imgTex("rustN", .5, 1); m.roughnessMap = imgTex("rustR", .5, 1); m.color.setHex(0xaab8d8); m.roughness = 1; m.metalness = .35; m.needsUpdate = true; } });
  const fm = roomMeshes[0].material; fm.metalness = .35; fm.roughness = .5; fm.needsUpdate = true;
}
for (const k of ["rustC", "steelC"]) { if (TIMG[k].complete) setTimeout(labMetal, 0); else TIMG[k].addEventListener("load", labMetal); }

// ---- Spinne: weiße Teile = Plastic010, orange Teile = Metal034 (gelb, orange getönt) ----
function spiderMats() {
  const need = ["plaC", "mtlC"]; if (need.some(k => !TIMG[k].complete || !TIMG[k].naturalWidth)) return;
  const P = (m, k, rx, ry) => { m.map = imgTex(k + "C", rx, ry); m.normalMap = imgTex(k + "N", rx, ry); m.roughnessMap = imgTex(k + "R", rx, ry); m.normalScale.set(.8, .8); m.needsUpdate = true; };
  P(matLight, "pla", 1.5, 1.5); matLight.color.setHex(0xffffff); matLight.emissive.setHex(0x70757e); matLight.roughness = 1; matLight.metalness = .1;
  P(matBrass, "mtl", 1.5, 1.5); matBrass.color.setHex(0x4fa9a3); matBrass.roughness = 1; matBrass.metalness = .2; matBrass.emissive.setHex(0x0c2a28);
}
for (const k of ["plaC", "mtlC"]) { if (TIMG[k].complete) setTimeout(spiderMats, 0); else TIMG[k].addEventListener("load", spiderMats); }
function fenceMat(rx, ry) { return new THREE.MeshStandardMaterial({map:imgTex("fncC", rx, ry), alphaMap:imgTex("fncA", rx, ry), normalMap:imgTex("fncN", rx, ry), transparent:true, alphaTest:.5, side:THREE.DoubleSide, roughness:.6, metalness:.5, color:0xb8c0d0}); }
